// Store response time for this iteration
const responseTimes =
    JSON.parse(pm.collectionVariables.get("api07_responseTimes") || "[]");

responseTimes.push(pm.response.responseTime);

pm.collectionVariables.set(
    "api07_responseTimes",
    JSON.stringify(responseTimes)
);

// Every individual request must be below 2000 ms
pm.test("Response time is less than 2000 ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(2000);
});

// After the 10th request, calculate p95
if (pm.info.iteration === 9) {
    const times = responseTimes.slice().sort((a, b) => a - b);

    const p95Index = Math.ceil(times.length * 0.95) - 1;
    const p95 = times[p95Index];

    console.log("API-07 response times:", times);
    console.log("API-07 p95 response time:", p95 + " ms");

    pm.test("p95 response time is less than 2000 ms", function () {
        pm.expect(p95).to.be.below(2000);
    });
}

